// "Zuständige Stelle finden" (Bundesland → Kreis → Gemeinde) in 13 languages. Called from build.js.
// Municipality data: daten/gv/*.json, generated by .github/workflows/gemeindeverzeichnis.yml from the
// Destatis Gemeindeverzeichnis (GV100AD). Only official portals are linked; each URL was checked on LINKS_CHECKED
// (Länder-Serviceportale / Zuständigkeitsfinder, verwaltung.bund.de, BAMF-NAvI, BA-Dienststellensuche,
// BZSt-Finanzamtsuche, Orts- und Gerichtsverzeichnis der Justiz, 115.de). No authority addresses are guessed.
const fs = require("fs");
const path = require("path");
const LINKS_CHECKED = "09.11.2026";
// AGS Land key → [name, official portal]
const LAENDER = {
  "01": ["Schleswig-Holstein", "https://zufish.schleswig-holstein.de/"],
  "02": ["Hamburg", "https://www.hamburg.de/behoerdenfinder/"],
  "03": ["Niedersachsen", "https://www.service.niedersachsen.de/"],
  "04": ["Bremen", "https://www.service.bremen.de/startseite-1459"],
  "05": ["Nordrhein-Westfalen", "https://meineverwaltung.nrw/"],
  "06": ["Hessen", "https://verwaltungsportal.hessen.de/"],
  "07": ["Rheinland-Pfalz", "https://bus.rlp.de/"],
  "08": ["Baden-Württemberg", "https://www.service-bw.de/zufi"],
  "09": ["Bayern", "https://www.bayernportal.de/"],
  "10": ["Saarland", "https://service.saarland.de/"],
  "11": ["Berlin", "https://service.berlin.de/behoerden/"],
  "12": ["Brandenburg", "https://service.brandenburg.de/service/de/adressen/"],
  "13": ["Mecklenburg-Vorpommern", "https://www.mv-serviceportal.de/"],
  "14": ["Sachsen", "https://amt24.sachsen.de/zufi"],
  "15": ["Sachsen-Anhalt", "https://buerger.sachsen-anhalt.de/"],
  "16": ["Thüringen", "https://verwaltung.thueringen.de/"],
};
const FED = [
  ["Verwaltungsportal des Bundes", "https://verwaltung.bund.de/"],
  ["BAMF-NAvI", "https://bamf-navi.bamf.de/de/"],
  ["Bundesagentur für Arbeit – Dienststellen", "https://web.arbeitsagentur.de/portal/metasuche/suche/dienststellen"],
  ["BZSt – Finanzamtsuche", "https://www.bzst.de/DE/Service/Behoerdenwegweiser/Finanzamtsuche/finanzamtsuche_node.html"],
  ["Orts- und Gerichtsverzeichnis der Justiz", "https://www.justizadressen.nrw.de/de/justiz/suche"],
  ["115 – Behördennummer", "https://www.115.de/"],
];
const EXTRA_CSS = `.finder{display:grid;gap:12px;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:16px;margin:18px 0}
.finder label{display:grid;gap:4px;font-weight:600;font-size:15px}.finder select,.finder input{font:inherit;font-size:16px;width:100%;max-width:100%;padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:var(--bg);color:var(--ink)}
.finder select:disabled{opacity:.55}.msg{color:var(--muted);font-size:15px;margin:0}.res{border:2px solid var(--brand);border-radius:14px;padding:14px 16px;background:var(--card);margin:14px 0}.res h2{margin:0 0 10px;font-size:20px}
.res table{border:0}.res td{padding:6px 8px}ul.help small{display:block;font-weight:400;color:var(--muted)}ul.help a.land{border:2px solid var(--brand)}
@media(min-width:700px){.finder{grid-template-columns:1fr 1fr}.finder .full{grid-column:1/-1}}`;

module.exports = function ({ C, CSS, LOGO, LANGS, SITE, VORL, esc, rel, root, url, PAGES, out }) {
  const KEY = "stelle";
  const urls = [];
  for (const [lang] of LANGS) {
    const s = JSON.parse(fs.readFileSync(path.join(__dirname, "src", "stelle", lang + ".json"), "utf8"));
    const t = C[lang], u = t.ui;
    const dir = lang === "ar" ? "rtl" : "ltr";
    const others = Object.keys(PAGES).filter(k => k !== KEY);
    const alts = LANGS.map(([l]) => `<link rel="alternate" hreflang="${l}" href="${url(l, KEY)}">`).join("\n") + `\n<link rel="alternate" hreflang="x-default" href="${url("de", KEY)}">`;
    const faq = { "@context": "https://schema.org", "@type": "FAQPage", inLanguage: lang,
      mainEntity: s.faq.map(([q, a]) => ({ "@type": "Question", name: q, acceptedAnswer: { "@type": "Answer", text: a } })) };
    const crumbs = { "@context": "https://schema.org", "@type": "BreadcrumbList", itemListElement: [
      { "@type": "ListItem", position: 1, name: "Amtsbriefe", item: SITE + "/" },
      { "@type": "ListItem", position: 2, name: s.h1, item: url(lang, KEY) }] };
    const T = { choose: s.choose, loading: s.loading, noData: s.noData, landPortal: s.landPortal, landPortalNote: s.landPortalNote,
      rGem: s.rGem, rKreis: s.rKreis, rLand: s.rLand, rPlz: s.rPlz, rAgs: s.rAgs, rEw: s.rEw, copied: u.copied, dataNote: s.dataNote };
    const html = `<!doctype html>
<html lang="${lang}" dir="${dir}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(s.title)}</title>
<meta name="description" content="${esc(s.desc)}">
<link rel="canonical" href="${url(lang, KEY)}">
${alts}
<meta property="og:type" content="website"><meta property="og:title" content="${esc(s.h1)}"><meta property="og:description" content="${esc(s.desc)}"><meta property="og:url" content="${url(lang, KEY)}"><meta property="og:site_name" content="Amtsbriefe">
<meta property="og:image" content="https://amtsbriefe.de/og-image.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="amtsbriefe.de – Briefe an deutsche Ämter, kostenlos, in 13 Sprachen erklärt"><meta name="twitter:card" content="summary_large_image">
<meta name="theme-color" content="#1F4E8C">
<link rel="icon" href="data:image/svg+xml,${encodeURIComponent(LOGO.replace(' aria-hidden="true"', ' xmlns="http://www.w3.org/2000/svg"'))}">
<style>${CSS}
${EXTRA_CSS}</style>
<script type="application/ld+json">${JSON.stringify(faq)}</script>
<script type="application/ld+json">${JSON.stringify(crumbs)}</script>
<script data-goatcounter="https://amtsbriefede.goatcounter.com/count" async src="//gc.zgo.at/count.js"></script>
</head>
<body>
<header><div class="wrap"><a class="logo" href="${root(lang)}">${LOGO}Amtsbriefe</a>
<nav class="langs" aria-label="Sprache">${LANGS.map(([l, n]) => `<a href="${rel(lang, l, KEY)}" hreflang="${l}"${l === lang ? ' aria-current="page"' : ""}>${n}</a>`).join("")}</nav></div></header>
<main class="wrap">
<nav class="crumb"><a href="${root(lang)}">Amtsbriefe</a> › ${esc(s.h1)}</nav>
<h1>${esc(s.h1)}</h1>
<p class="intro">${esc(s.intro)}</p>
<form class="finder" id="finder" onsubmit="return false">
<label>${esc(s.lLand)}<select id="f-land"><option value="">${esc(s.choose)}</option>${Object.entries(LAENDER).sort((a, b) => a[1][0].localeCompare(b[1][0], "de")).map(([k, [n]]) => `<option value="${k}">${esc(n)}</option>`).join("")}</select></label>
<label>${esc(s.lKreis)}<select id="f-kreis" disabled><option value="">${esc(s.choose)}</option></select></label>
<label class="full">${esc(s.lGem)}<input id="f-q" type="search" autocomplete="off" placeholder="${esc(s.search)}" disabled list="f-dl"><datalist id="f-dl"></datalist></label>
<label class="full"><span class="sr" hidden>${esc(s.lGem)}</span><select id="f-gem" disabled aria-label="${esc(s.lGem)}"><option value="">${esc(s.choose)}</option></select></label>
<p class="msg full" id="f-msg" aria-live="polite"></p>
</form>
<div class="res" id="res" hidden>
<h2>${esc(s.resTitle)}</h2>
<table id="res-t"></table>
<p><button type="button" class="act" id="res-copy">${esc(s.copyBtn)}</button></p>
</div>
<h2>${esc(s.portalTitle)}</h2>
<ul class="help" id="land-links"><li id="land-li" hidden><a class="land" id="land-a" href="https://www.115.de/" rel="noopener" target="_blank"></a></li>
${FED.map(([n, h], i) => `<li><a href="${h}" rel="noopener" target="_blank">${esc(n)} ↗<small>${esc(s.fed[i])}</small></a></li>`).join("\n")}
</ul>
<p class="note">${esc(s.why)}</p>
<h2>${esc(s.stepsTitle)}</h2>
<ol class="steps">${s.steps.map(([h, x]) => `<li><h3>${esc(h)}</h3><p>${esc(x)}</p></li>`).join("")}</ol>
<h2>${esc(s.faqTitle)}</h2>
${s.faq.map(([q, a]) => `<details><summary>${esc(q)}</summary><p class="lt">${esc(a)}</p></details>`).join("\n")}
<p class="other"><strong>${esc(u.other)}:</strong> ${others.map(o => `<a href="${rel(lang, lang, o)}">${esc(t[o].h1)}</a>`).join(" · ")} · <a href="${root(lang)}">${esc(u.home)}</a></p>
<p class="src" id="src">${esc(s.linksNote.replace("{D}", LINKS_CHECKED))}<br><span id="src-gv"></span></p>
<p class="note">${esc(u.disclaimer)}</p>
</main>
<footer><div class="wrap"><a href="${root(lang)}">Amtsbriefe</a><a href="${lang === "de" ? "" : "/" + lang}/vorlagen.html">${VORL[lang] || VORL.de}</a><a href="${root(lang)}impressum.html">Impressum</a><a href="${root(lang)}datenschutz.html">Datenschutz</a></div></footer>
<script>
(function(){
var T=${JSON.stringify(T)},L=${JSON.stringify(LAENDER)};
var $=function(i){return document.getElementById(i)};
var land=$("f-land"),kreis=$("f-kreis"),q=$("f-q"),gem=$("f-gem"),msg=$("f-msg"),res=$("res"),dl=$("f-dl"),la=$("land-a");
var data=null,meta=null,col=window.Intl&&Intl.Collator?new Intl.Collator("de"):{compare:function(a,b){return a<b?-1:a>b?1:0}};
function esc(x){return String(x).replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
function opts(sel,list){sel.innerHTML='<option value="">'+esc(T.choose)+'</option>'+list.map(function(o){return '<option value="'+esc(o[0])+'">'+esc(o[1])+'</option>'}).join("");sel.disabled=!list.length}
fetch("/daten/gv/meta.json").then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(m){meta=m;if(m.stand)$("src-gv").textContent=T.dataNote.replace("{S}",m.stand)}).catch(function(){});
land.onchange=function(){var k=land.value;res.hidden=true;data=null;opts(kreis,[]);opts(gem,[]);q.value="";q.disabled=true;dl.innerHTML="";msg.textContent="";
 if(!k){la.parentNode.hidden=true;return}
 la.parentNode.hidden=false;la.href=L[k][1];la.innerHTML=esc(T.landPortal.replace("{L}",L[k][0]))+' ↗<small>'+esc(T.landPortalNote)+'</small>';
 msg.textContent=T.loading;
 fetch("/daten/gv/"+k+".json").then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(d){if(land.value!==k)return;data=d;msg.textContent="";
  d.k.sort(function(a,b){return col.compare(a[1],b[1])});d.g.sort(function(a,b){return col.compare(a[1],b[1])});
  opts(kreis,d.k);q.disabled=false;dl.innerHTML=d.g.map(function(g){return '<option value="'+esc(g[1])+' ('+esc(g[2])+')">'}).join("");
  if(d.k.length===1){kreis.value=d.k[0][0];kreis.onchange()}
 }).catch(function(){msg.textContent=T.noData});
};
kreis.onchange=function(){res.hidden=true;if(!data)return;var k=kreis.value;opts(gem,k?data.g.filter(function(g){return g[0].slice(0,5)===k}).map(function(g){return[g[0],g[1]]}):[]);if(gem.options.length===2){gem.value=gem.options[1].value;gem.onchange()}};
gem.onchange=function(){show(gem.value)};
q.oninput=function(){if(!data)return;var v=q.value.trim().toLowerCase();if(!v)return;var hit=data.g.filter(function(g){return(g[1]+" ("+g[2]+")").toLowerCase()===v})[0];if(hit){kreis.value=hit[0].slice(0,5);kreis.onchange();gem.value=hit[0];show(hit[0])}};
function show(ags){var g=data&&data.g.filter(function(x){return x[0]===ags})[0];if(!g){res.hidden=true;return}
 var kr=data.k.filter(function(x){return x[0]===ags.slice(0,5)})[0];
 var rows=[[T.rGem,g[1]],[T.rPlz,g[2]],[T.rKreis,kr?kr[1]:""],[T.rLand,L[ags.slice(0,2)][0]],[T.rAgs,ags]];if(g[3])rows.push([T.rEw,Number(g[3]).toLocaleString("de-DE")]);
 $("res-t").innerHTML=rows.map(function(r){return "<tr><td>"+esc(r[0])+"</td><td>"+esc(r[1])+"</td></tr>"}).join("");
 res.hidden=false;res.dataset.txt=g[1]+", "+g[2]+"\\n"+(kr?kr[1]+"\\n":"")+L[ags.slice(0,2)][0];}
$("res-copy").onclick=function(){var b=this,o=b.textContent,t=res.dataset.txt||"";var done=function(){b.textContent=T.copied;setTimeout(function(){b.textContent=o},1800)};
 try{navigator.clipboard.writeText(t).then(done,done)}catch(e){done()}};
})();
</script>
</body>
</html>
`;
    const d = lang === "de" ? out : path.join(out, lang);
    fs.writeFileSync(path.join(d, PAGES[KEY] + ".html"), html);
    urls.push(url(lang, KEY));
  }
  console.log("built", urls.length, "Zuständige-Stelle pages");
};
